def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the 3-cell-thick color strip. Each slot is uniform through its
    # thickness; its color sequence specifies the order of the copies.
    key = None
    key_cells = set()
    for r in range(h - 2):
        c = 0
        while c < w:
            if grid[r][c] == 0 or grid[r+1][c] != grid[r][c] or grid[r+2][c] != grid[r][c]:
                c += 1
                continue
            start = c
            seq = []
            while c < w and grid[r][c] != 0 and grid[r+1][c] == grid[r][c] and grid[r+2][c] == grid[r][c]:
                seq.append(grid[r][c]); c += 1
            if len(seq) >= 2:
                key = seq
                key_cells = {(rr,cc) for rr in range(r,r+3) for cc in range(start,c)}
                break
        if key is not None:
            break
    if key is None:
        raise ValueError('color strip not found')

    # Extract connected non-key objects whose color occurs in the sequence.
    by_color = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color and (r,c) not in key_cells:
                by_color.setdefault(color, set()).add((r,c))
    components = []
    for color, remaining0 in by_color.items():
        remaining = set(remaining0)
        while remaining:
            stack = [remaining.pop()]
            comp = set(stack)
            while stack:
                r,c = stack.pop()
                for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if q in remaining:
                        remaining.remove(q); comp.add(q); stack.append(q)
            if color in key:
                components.append((len(comp), color, comp))
    if not components:
        raise ValueError('matching silhouette not found')
    _, anchor_color, comp = max(components, key=lambda item:item[0])
    rmin = min(r for r,c in comp); cmin = min(c for r,c in comp)
    mask = {(r-rmin,c-cmin) for r,c in comp}
    shape_h = max(dr for dr,dc in mask)+1
    idx = key.index(anchor_color)

    out = [[0 for _ in range(w)] for _ in range(h)]
    for i, color in enumerate(key):
        top = rmin + (i-idx)*shape_h
        for dr,dc in mask:
            rr,cc = top+dr,cmin+dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out
