            if grid[r][c] == 0 or grid[r+1][c] != grid[r][c] or grid[r+2][c] != grid[r][c]:
                c += 1
                continue
            start = c
            seq = []
            while c < w and grid[r][c] != 0 and grid[r+1][c] == grid[r][c] and grid[r+2][c] == grid[r][c]:
                seq.append(grid[r][c]); c += 1
            if len(seq) >= 2:
                key = seq
                key_cells = {(rr, cc) for rr in range(r, r+3) for cc in range(start, c)}
                break
        if key is not None:
            break
    if key is None:
        raise ValueError('color strip not found')

