    cells = cells_by_color[anchor_color]
    rmin = min(r for r, c in cells)
    cmin = min(c for r, c in cells)
    mask = {(r-rmin, c-cmin) for r, c in cells}
    shape_h = max(dr for dr, dc in mask) + 1
    idx = key.index(anchor_color)

